selector_to_html = {"a[href=\"user_guide.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">User Guide<a class=\"headerlink\" href=\"#user-guide\" title=\"Link to this heading\">#</a></h1><p>For</p>", "a[href=\"#registration\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Registration<a class=\"headerlink\" href=\"#registration\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#selecting-the-image\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Selecting the image<a class=\"headerlink\" href=\"#selecting-the-image\" title=\"Link to this heading\">#</a></h3><p>Recommended \u2014 enable cellpose with <code class=\"docutils literal notranslate\"><span class=\"pre\">algorithm=\"cellpose\"</span></code> and pick <code class=\"docutils literal notranslate\"><span class=\"pre\">img</span></code>:</p>", "a[href=\"pipeline_comparison.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Pipeline Comparison<a class=\"headerlink\" href=\"#pipeline-comparison\" title=\"Link to this heading\">#</a></h1><p>This page compares how different calcium imaging analysis pipelines handle \u0394F/F calculation, neuropil correction, and spike deconvolution.</p>", "a[href=\"#detection-preprocessing\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Detection Preprocessing<a class=\"headerlink\" href=\"#detection-preprocessing\" title=\"Link to this heading\">#</a></h2><p>These steps are applied to the registered movie before ROI detection:</p>", "a[href=\"#spatial-high-pass-spatial-hp-cp-upstream-cellpose-settings-highpass-spatial\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Spatial high-pass: <code class=\"docutils literal notranslate\"><span class=\"pre\">spatial_hp_cp</span></code> (upstream <code class=\"docutils literal notranslate\"><span class=\"pre\">cellpose_settings.highpass_spatial</span></code>)<a class=\"headerlink\" href=\"#spatial-high-pass-spatial-hp-cp-upstream-cellpose-settings-highpass-spatial\" title=\"Link to this heading\">#</a></h3><p>Integer, default 0 (off). When &gt; 0, the chosen <code class=\"docutils literal notranslate\"><span class=\"pre\">img</span></code> is normalized to [0, 1] and a\nGaussian-blurred copy (sigma = <code class=\"docutils literal notranslate\"><span class=\"pre\">diameter</span> <span class=\"pre\">\u00d7</span> <span class=\"pre\">spatial_hp_cp</span></code>) is subtracted twice, removing\nillumination gradients and sharpening cell boundaries. It applies to whichever <code class=\"docutils literal notranslate\"><span class=\"pre\">img</span></code> you\nselect and does <strong>not</strong> modify the stored <code class=\"docutils literal notranslate\"><span class=\"pre\">ops[\"meanImg\"]</span></code> or <code class=\"docutils literal notranslate\"><span class=\"pre\">ops[\"max_proj\"]</span></code>.</p>", "a[href=\"#post-detection-all-modes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Post-Detection (All Modes)<a class=\"headerlink\" href=\"#post-detection-all-modes\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#detection-anatomical-mode-cellpose\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Detection: Anatomical Mode (Cellpose)<a class=\"headerlink\" href=\"#detection-anatomical-mode-cellpose\" title=\"Link to this heading\">#</a></h2><p>Cellpose segments one static image, chosen by <code class=\"docutils literal notranslate\"><span class=\"pre\">cellpose_settings.img</span></code>. Suite2p 1.1.0\naccepts three values:</p>", "a[href=\"#what-each-projection-image-contains\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">What each projection image contains<a class=\"headerlink\" href=\"#what-each-projection-image-contains\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#detection-functional-mode\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Detection: Functional Mode<a class=\"headerlink\" href=\"#detection-functional-mode\" title=\"Link to this heading\">#</a></h2><p>When <code class=\"docutils literal notranslate\"><span class=\"pre\">ops[\"anatomical_only\"]</span> <span class=\"pre\">=</span> <span class=\"pre\">0</span></code>:</p>", "a[href=\"#processing-flow\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Processing Flow<a class=\"headerlink\" href=\"#processing-flow\" title=\"Link to this heading\">#</a></h1><p>High-level overview of all processing steps executed by <code class=\"docutils literal notranslate\"><span class=\"pre\">lsp.pipeline()</span></code>.</p>", "a[href=\"#lsp-pipeline-additional-steps\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">lsp.pipeline() Additional Steps<a class=\"headerlink\" href=\"#lsp-pipeline-additional-steps\" title=\"Link to this heading\">#</a></h2><p>These are applied by <code class=\"docutils literal notranslate\"><span class=\"pre\">lsp.pipeline()</span></code> after suite2p completes:</p>", "a[href=\"postprocessing.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Postprocessing Functions<a class=\"headerlink\" href=\"#postprocessing-functions\" title=\"Link to this heading\">#</a></h1><p>This guide covers the postprocessing functions available in LBM-Suite2p-Python for analyzing and refining calcium imaging traces after Suite2p extraction.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
